protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");
        entity.HasIndex(p => p.Sku);

        // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
        // Existing 500K documents and direct SQL queries use "Discriminator", so preserve it.
        entity.HasDiscriminator<string>("Discriminator");

        // EF Core 9 changed the default id format from "EntityType|Key" to just "Key".
        // Existing documents use "Product|123" format, so opt back into the legacy format.
        entity.HasPartitionKey(p => p.Id);
        entity.Property(p => p.Id).ToJsonProperty("id")
              .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();
    });
}

protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
{
    // Preserve the EF Core 8 id format: "EntityType|KeyValue"
    configurationBuilder.Conventions.Add(_ =>
        new Microsoft.EntityFrameworkCore.Cosmos.Metadata.Conventions.CosmosNoSyntheticIdConvention());
}

