using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
            // Existing 500K documents and direct SQL queries use "Discriminator", so preserve it.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed the default id format from "EntityType|Key" to just "Key".
            // Existing documents use "Product|123" format, so we add an explicit __id shadow
            // property mapped to the JSON "id" with a generator that produces the legacy format.
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();
        });
    }
}

/// <summary>
/// Generates id values in the EF Core 8 Cosmos format: "EntityType|KeyValue".
/// Required for backward compatibility with 500K existing documents.
/// </summary>
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    public override string Next(EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();
        var primaryKey = entry.Property("Id").CurrentValue;
        return $"{entityType}|{primaryKey}";
    }
}

